/** Output-only seen-ask receipt: never consent, an answer or a mutation grant. */
export function projectOnboardingPendingAsks(output, options) {
  const asks = output?.nextAction?.pendingAsks;
  if (output?.schema !== "pipeline.project-onboarding.v4" || !Array.isArray(asks) || asks.length === 0) return output;
  const encoded = JSON.stringify({ root: output.root, runner: output.runner, intent: options.intent, asks });
  if (asks.length > 16 || Buffer.byteLength(encoded, "utf8") > 1_048_576) {
    return { schema: "pipeline.onboarding-pending-asks-summary.v1", status: "unavailable", root: output.root,
      code: "ONBOARDING-ASK-PROJECTION-BOUND", nextAction: null };
  }
  const sha = value => createHash("sha256").update(value).digest("hex");
  const digest = sha(encoded);
  const fullArgv = [fileURLToPath(import.meta.url), "inspect", "--root", output.root, "--intent", options.intent];
  if (output.runner) fullArgv.push("--runner", output.runner);
  const fullReadAction = { kind: "command", executable: "node", argv: fullArgv, mutation: false,
    requiresConfirmation: false, expected: { schema: output.schema } };
  if (options.shownAsksSha256 !== digest) {
    return { ...output, nextAction: { ...output.nextAction, pendingAsksReadback: {
      schema: "pipeline.onboarding-pending-asks-readback.v1", sha256: digest,
      routineInspectAction: { ...fullReadAction, argv: [...fullArgv, "--shown-asks-sha256", digest] },
    } } };
  }
  const references = asks.map((ask, index) => {
    const inputs = Array.isArray(ask?.inputs) ? ask.inputs : ask?.input ? [ask.input] : [];
    const inputNames = inputs.map(input => input?.name);
    if (ask?.kind !== "collect-input" || inputNames.some(name => typeof name !== "string" || Buffer.byteLength(name) > 128)
      || inputNames.length > 32) return null;
    return { index, sha256: sha(JSON.stringify(ask)), inputNames };
  });
  if (references.some(reference => reference === null)) return output;
  // No question is considered answered: the only executable action retrieves
  // the full current inspection again before any mutating/answer-bearing step.
  return { schema: "pipeline.onboarding-pending-asks-summary.v1", status: "pending-asks", root: output.root,
    runner: output.runner, intent: options.intent, observedStatus: output.status,
    asksSha256: digest, asks: references, nextAction: fullReadAction };
}

